def show_composicion_preview(payload: Dict[str, Any], height: int = 1120):
    # La plantilla mide 794x1123px (A4 a 96dpi). Se deja scroll para que Streamlit no la corte.
    components.html(render_composicion_html(payload), height=height, scrolling=True)


def _img_from_data_uri(data_uri: Optional[str], max_w: float, max_h: float):
    if not data_uri:
        return Paragraph("", ParagraphStyle("empty", fontSize=1))
    try:
        raw_b64 = data_uri.split(",", 1)[1]
        bio = io.BytesIO(base64.b64decode(raw_b64))
        img = Image(bio)
        img._restrictSize(max_w, max_h)
        return img
    except Exception:
        return Paragraph("", ParagraphStyle("empty", fontSize=1))


def _body_reportlab(max_w: float, max_h: float):
    bio = io.BytesIO(base64.b64decode(BODY_SILHOUETTE_B64))
    img = Image(bio)
    img._restrictSize(max_w, max_h)
    return img


def _p(text: Any, style: ParagraphStyle) -> Paragraph:
    return Paragraph(escape(str(text if text not in (None, "") else "—")), style)


def _buscar_navegador_local():
    """Busca Chrome/Chromium/Edge en Windows y Linux."""
    candidatos = [
        os.environ.get("CHROME_PATH"),
        os.environ.get("CHROMIUM_PATH"),

        # Streamlit Cloud / Linux
        "/usr/bin/chromium",
        "/usr/bin/chromium-browser",
        "/usr/bin/google-chrome",
        "/usr/bin/google-chrome-stable",

        # Windows local
        r"C:\Program Files\Google\Chrome\Application\chrome.exe",
        r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
        r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
        r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
    ]

    for path in candidatos:
        if path and os.path.exists(path):
            return path

    return None


async def _html_to_pdf_async(html: str) -> bytes:
    from pyppeteer import launch

    navegador = _buscar_navegador_local()
    if not navegador:
        raise RuntimeError(
            "No encontré Chrome ni Edge instalado para generar el PDF. "
            "Instalá Google Chrome o configurá la variable CHROME_PATH con la ruta de chrome.exe."
        )

    browser = await launch(
        executablePath=navegador,
        headless=True,
        args=[
            "--no-sandbox",
            "--disable-setuid-sandbox",
            "--disable-dev-shm-usage",
            "--disable-gpu",
        ],
        handleSIGINT=False,
        handleSIGTERM=False,
        handleSIGHUP=False,
    )
    try:
        page = await browser.newPage()
        await page.setViewport({"width": 794, "height": 1123, "deviceScaleFactor": 1})
        # pyppeteer 2.0 no acepta waitUntil en setContent().
        # Cargamos el HTML y esperamos brevemente a que el navegador pinte estilos/inline SVG.
        await page.setContent(html)
        await page.waitFor(300)
        try:
            await page.emulateMedia("screen")
        except TypeError:
            await page.emulateMedia(mediaType="screen")
        pdf = await page.pdf({
            "printBackground": True,
            "width": "794px",
            "height": "1123px",
            "margin": {"top": "0px", "right": "0px", "bottom": "0px", "left": "0px"},
            "preferCSSPageSize": True,
        })
        return pdf
    finally:
        await browser.close()


def _run_async_pdf(html: str) -> bytes:
    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)
        return loop.run_until_complete(_html_to_pdf_async(html))
    finally:
        asyncio.set_event_loop(None)
        loop.close()


def build_composicion_pdf(payload: Dict[str, Any]) -> bytes:
    html = render_composicion_html(payload)
    return _run_async_pdf(html)